import{z as o,x as s,o as A,c as n,q as B,j as r,D as a,d as l,s as t,S as i}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"验证器瓶颈","description":"","frontmatter":{"title":"验证器瓶颈","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/verifier-bottleneck.md","filePath":"llm/verifier-bottleneck.md","lastUpdated":1791413859000}'),p={name:"llm/verifier-bottleneck.md"};function d(m,E,F,C,_,h){const e=s("Mermaid");return A(),n("div",null,[E[2]||(E[2]=B('<h1 id="验证器瓶颈" tabindex="-1">验证器瓶颈 <a class="header-anchor" href="#验证器瓶颈" aria-label="Permalink to &quot;验证器瓶颈&quot;">​</a></h1><div class="epigraph"><p>自训练的上限不在生成侧——采样可以无限重试——而在验证侧：选择算子有多准，回路就能把策略推到多远。</p><footer>—— 据 Gao 等 RM 过优化缩放律；Brown 等 Large Language Monkeys 整理</footer></div><p><a href="/llm/model-collapse-empirics">上一课</a>把递归自食的后果钉在尾部丢失与熵收缩，并给了回混与累积两条不坍缩条件。本课把镜头对准回路里决定「什么算通过」的部件：即使分布不坍缩，自训练的上限也由验证质量决定。<a href="/llm/math-verifier-equivalence">数学验证器与等价</a>与<a href="/llm/code-verifier-unittests">代码验证器</a>已把假阳、假阴的具体来源讲清；本课讲这些误差如何顺着回路变成策略的偏移，以及为什么优化压力会放大它。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>生成侧与验证侧不对称：每题可以采样任意多条，覆盖随 \\(K\\) 增长，而选择只有验证器那一步。Brown 等 2024 的大规模重采样实验口径：足够大的 \\(K\\) 下，真实能力覆盖显著高于验证器选出的准确率——这个差距就是验证器瓶颈的宽度。误差两类，后果相反：假阳让错的解法被通过、进入训练数据；假阴把对的解法拒掉、正确的示范被丢弃。<a href="/llm/verifiable-reward">可验证奖励</a>课的结论在这里兑现：抽取器与运行规范是 \\(R\\) 的一部分，它们的系统性偏差不是噪声。</p><p><span class="marginnote">直觉类比：生成侧像撒一千张渔网出海，撒得越多总有网有鱼；验证侧是码头上只有一个质检员，他看走眼一条，那条鱼就永远定错了。渔网加倍救不了质检员的眼神——这就是「重采样填不平验证缺口」的直觉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>治理按瓶颈位置分三步。测瓶颈：抽样人工复核通过样本（假阳率）与被拒样本（假阴率），按题型分层；用金标探针构造「满足判据但答案错」的样本测假阳。堵假阳：判据集成（多验证器投票）、隐藏与随机化测例（代码课结论：训练用例会被硬编码）、训练与评测同源脚本（数学课结论）、格式判据配内容复核。减假阴：等价规范声明完整（数值、符号、整数化三条口径）、被拒样本抽样回放人工判定、对全零组换题而不是硬训。兜底：KL 锚与检查点早停——<a href="/llm/rlvr">RLVR</a>课测到真值验证器仍会过优化，误差非零的验证器只会更早。</p>',8)),(A(),r(i,null,{default:a(()=>[t(e,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%87%AA%E8%AE%AD%E7%BB%83%E5%9B%9E%E8%B7%AF%E5%BC%80%E8%B7%91%E5%89%8D%22%5D%20--%3E%20M%5B%22%E6%B5%8B%E7%93%B6%E9%A2%88%3A%20%E6%8A%BD%E6%A0%B7%E4%BA%BA%E5%B7%A5%E5%A4%8D%E6%A0%B8%3Cbr%2F%3E%E5%88%86%E5%B1%82%E4%BC%B0%E8%AE%A1%E5%81%87%E9%98%B3%E7%8E%87%E4%B8%8E%E5%81%87%E9%98%B4%E7%8E%87%22%5D%0A%20%20M%20--%3E%20FA%7B%22%E8%AF%AF%E5%B7%AE%E9%9B%86%E4%B8%AD%E5%9C%A8%E5%93%AA%E4%B8%80%E4%BE%A7%3F%22%7D%0A%20%20FA%20--%3E%7C%22%E5%81%87%E9%98%B3%E5%A4%9A%22%7C%20BA%5B%22%E5%A0%B5%E5%81%87%E9%98%B3%3A%20%E5%A4%9A%E9%AA%8C%E8%AF%81%E5%99%A8%E6%8A%95%E7%A5%A8%3Cbr%2F%3E%E9%9A%90%E8%97%8F%E6%B5%8B%E4%BE%8B%20%2F%20%E8%AE%AD%E8%AF%84%E5%90%8C%E6%BA%90%E8%84%9A%E6%9C%AC%22%5D%0A%20%20FA%20--%3E%7C%22%E5%81%87%E9%98%B4%E5%A4%9A%22%7C%20BN%5B%22%E5%87%8F%E5%81%87%E9%98%B4%3A%20%E7%AD%89%E4%BB%B7%E8%A7%84%E8%8C%83%E8%A1%A5%E5%85%A8%3Cbr%2F%3E%E8%A2%AB%E6%8B%92%E6%A0%B7%E6%9C%AC%E5%9B%9E%E6%94%BE%20%2F%20%E5%85%A8%E9%9B%B6%E7%BB%84%E6%8D%A2%E9%A2%98%22%5D%0A%20%20BA%20--%3E%20KL%5B%22KL%20%E9%94%9A%E4%B8%8E%E6%97%A9%E5%81%9C%E5%85%9C%E5%BA%95%3Cbr%2F%3E%E9%99%90%E5%88%B6%E6%94%BE%E5%A4%A7%E7%B3%BB%E6%95%B0%22%5D%0A%20%20BN%20--%3E%20KL%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<p><span class="marginnote">数字实例：某题集上人工复核发现采样 200 条里有 120 条存在正确解法（覆盖 60%），而验证器最终选出的样本真确率只有 25%——缺口就是 35 个百分点。把采样数从 200 加到 2000 只会继续抬高覆盖，这道缺口一分都不会缩小；能缩它的只有修验证器本身。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><span class="marginnote">Gao 等 2023 的缩放律口径：代理奖励与金标的间隙随优化压力（KL 预算）放大。验证器误差不是恒定的背景噪声——回路施加的优化压力越大，同一条判据漏洞吃掉的份额越大。</span></p><p>偏移的因果链：假阳样本进入训练，策略分布向「能通过验证器」的区域移动，下一代采样在该区域更密，同型漏洞被更频繁命中，权重把漏洞学进去——回路把一次性的判据缺陷变成迭代放大的策略偏移。假阴走另一条链：组相对优势下，某题全组被误判为零则无梯度（<a href="/llm/dynamic-sampling-rl">动态采样</a>课的无效组），正确解法的探索白做；系统性假阴（等价规范不认某类写法）把整类正确解法推离支撑——与坍缩课的尾部丢失同构，只是截断来自判据而非采样。两条链合流于一个事实：回路实际优化的是 \\(v\\) 而非真值 \\(R^*\\)，收敛点是 \\(v\\) 上的最优；\\(\\|v-R^*\\|\\) 在支撑上的分布，就是策略与真实能力的距离。</p>',4)),(A(),r(i,null,{default:a(()=>[t(e,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E9%AA%8C%E8%AF%81%E5%99%A8%E8%AF%AF%E5%B7%AE%EF%BC%9A%E5%81%87%E9%98%B3%E4%B8%8E%E5%81%87%E9%98%B4%22%5D%20--%3E%20FA%5B%22%E5%81%87%E9%98%B3%E6%A0%B7%E6%9C%AC%E8%BF%9B%E8%AE%AD%E7%BB%83%22%5D%0A%20%20V%20--%3E%20FN%5B%22%E5%81%87%E9%98%B4%E6%A0%B7%E6%9C%AC%E8%A2%AB%E4%B8%A2%E5%BC%83%EF%BC%9A%E5%85%A8%E9%94%99%E7%BB%84%E6%97%A0%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20FA%20--%3E%20SHIFT%5B%22%E7%AD%96%E7%95%A5%E5%90%91%E5%8F%AF%E9%80%9A%E8%BF%87%E5%8C%BA%E5%9F%9F%E5%81%8F%E7%A7%BB%22%5D%0A%20%20SHIFT%20--%3E%20DENS%5B%22%E4%B8%8B%E4%B8%80%E4%BB%A3%E9%87%87%E6%A0%B7%E5%9C%A8%E6%BC%8F%E6%B4%9E%E5%8C%BA%E6%9B%B4%E5%AF%86%22%5D%0A%20%20DENS%20--%3E%20AMP%5B%22%E8%AF%AF%E5%B7%AE%E8%A2%AB%E8%BF%AD%E4%BB%A3%E6%94%BE%E5%A4%A7%EF%BC%8C%E5%86%99%E8%BF%9B%E6%9D%83%E9%87%8D%22%5D%0A%20%20FN%20--%3E%20TAIL%5B%22%E6%AD%A3%E7%A1%AE%E8%A7%A3%E6%B3%95%E7%A7%BB%E5%87%BA%E6%94%AF%E6%92%91%EF%BC%9A%E5%B0%BE%E9%83%A8%E6%8D%9F%E5%A4%B1%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p>治理三步分别插在这条链的环节上：测瓶颈量化入口误差，堵假阳与减假阴削弱偏移与截断两个分支，KL 锚限制放大系数——但都只能推迟与收窄，不能归零。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课假设验证器在迭代间固定；验证器自身随回路升级（自出测例、模型当裁判）引入新的循环依赖，属于下一单元。假阳与假阴的治理互相顶：更严的判据压假阳、抬假阴——权衡怎么摆，是下一课 RLVR 设计空间的主题。生成侧的覆盖测量（pass@k 与提交预算）见<a href="/llm/pass-at-k">pass@k</a>课，不重复。</p><p><span class="marginnote">常见误区：初学者容易以为「多训几轮，回路自己会把验证器的误差磨掉」。实际上回路优化的是验证器 \\(v\\) 而非真值 \\(R^*\\)：误差非零时，迭代只会把策略更快推向 \\(v\\) 的漏洞区；KL 锚只能推迟与收窄，不能归零。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>生成可以重试，验证只有一次选择：瓶颈宽度是覆盖与选出质量之差。</li><li>假阳经回路变成策略偏移并被迭代放大；假阴把正确解法推离支撑。</li><li>回路优化的是 \\(v\\) 而非 \\(R^*\\)；KL 预算放大间隙。</li><li>治理：测误差率、判据集成与隐藏测例堵假阳、规范完整与全零组换题减假阴、KL 锚兜底。</li><li>出处：Gao 等 2023 过优化缩放律；Brown 等 2024 重采样覆盖；Cobbe 等 GSM8K；数学与代码验证器两课。</li></ul>',6))])}const f=o(p,[["render",d]]);export{c as __pageData,f as default};
